import { Component } from '@angular/core';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  usuario = '';
  senha = '';
  erro = false;

  constructor() { }

  // ngOnInit não utilizado

  login() {
    // Exemplo de autenticação simples (substitua por lógica real)
    if (this.usuario === 'admin' && this.senha === 'admin') {
      this.erro = false;
      alert('Login realizado com sucesso!');
      // Redirecionar para área administrativa se desejar
    } else {
      this.erro = true;
    }
  }
}
<div class="popup-backdrop" (click)="fecharLogin($event)">
	<div class="popup-login" (click)="$event.stopPropagation()">
		<button class="btn-close float-end" aria-label="Fechar" (click)="fecharLogin($event)"></button>
		<h2 class="mb-3">Login Administrativo</h2>
		<form (ngSubmit)="login()" #loginForm="ngForm">
			<div class="mb-3">
				<label for="usuario" class="form-label">Usuário</label>
				<input id="usuario" name="usuario" class="form-control" [(ngModel)]="usuario" required />
			</div>
			<div class="mb-3">
				<label for="senha" class="form-label">Senha</label>
				<input id="senha" name="senha" class="form-control" [(ngModel)]="senha" required type="password" />
			</div>
			<button class="btn btn-primary w-100" type="submit" [disabled]="!loginForm.form.valid">Entrar</button>
		</form>
		<div *ngIf="erro" class="erro-login mt-2">Usuário ou senha inválidos.</div>
	</div>
</div>
